function subPageHtml(data) {
  const json = JSON.stringify(data).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  return SUB_PAGE_TPL.replace('__DATA__', () => json);
}

const UserStore = {
  file: null, dirty: false, live: new Map(), recs: new Set(), ticker: null,
  data: { users: [], settings: { requireUser: false } },
  init(dir) {
    if (this.file) return;
    this.file = path.join(dir, 'users.json');
    try {
      const j = JSON.parse(fs.readFileSync(this.file, 'utf8'));
      if (j && Array.isArray(j.users)) this.data = { users: j.users, settings: Object.assign({ requireUser: false }, j.settings || {}) };
    } catch {}
    const t = setInterval(() => this.flush(), 10000);
    if (t.unref) t.unref();
    process.on('exit', () => this.flush());
    for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, () => { this.flush(); process.exit(0); });
  },
  flush() {
    if (!this.dirty || !this.file) return;
    try { fs.writeFileSync(this.file + '.tmp', JSON.stringify(this.data)); fs.renameSync(this.file + '.tmp', this.file); this.dirty = false; } catch {}
  },
  get(id) { return this.data.users.find(u => u.id === id); },
  state(u) {
    if (!u.enabled) return 'disabled';
    if (u.expireAt && Date.now() >= u.expireAt) return 'expired';
    if (u.limitBytes && u.used >= u.limitBytes) return 'limited';
    return 'active';
  },
  allowed(id) { const u = this.get(id); return !!u && this.state(u) === 'active'; },
  create(b) {
    const name = String(b.name || '').trim().slice(0, 40);
    if (!name) throw new UserError('نام کاربر را وارد کن.');
    if (this.data.users.some(u => u.name.toLowerCase() === name.toLowerCase())) throw new UserError('این نام قبلاً استفاده شده.');
    const gb = Number(b.limitGB || 0), days = Math.floor(Number(b.days || 0));
    if (!isFinite(gb) || gb < 0 || gb > 100000) throw new UserError('حجم نامعتبر است.');
    if (!isFinite(days) || days < 0 || days > 3650) throw new UserError('مدت نامعتبر است.');
    const proto = String(b.proto || '').trim();
    if (proto && proto.length > 40) throw new UserError('پروتکل نامعتبر است.');
    const u = { id: crypto.randomBytes(9).toString('base64url'), name, proto, limitBytes: Math.round(gb * 1073741824), used: 0, up: 0, lastOnline: 0, createdAt: Date.now(), expireAt: days ? Date.now() + days * 86400000 : 0, enabled: true };
    this.data.users.push(u); this.dirty = true; this.flush();
    return u;
  },
  remove(id) {
    const i = this.data.users.findIndex(u => u.id === id);
    if (i < 0) throw new UserError('کاربر پیدا نشد.');
    const [u] = this.data.users.splice(i, 1); this.dirty = true; this.flush();
    return u;
  },
  tagUri(uri, u, type) {
    uri = String(uri || '');
    const metered = type === undefined ? true : METERED_TYPES.test(type);
    if (/^vmess:\/\//i.test(uri)) {
      try {
        const j = JSON.parse(Buffer.from(uri.slice(8), 'base64').toString('utf8'));
        if (metered && j.path) j.path = j.path + (String(j.path).includes('?') ? '&' : '?') + 'u=' + u.id;
        j.ps = (j.ps ? j.ps + ' • ' : '') + u.name;
        return 'vmess://' + Buffer.from(JSON.stringify(j)).toString('base64');
      } catch { return uri; }
    }
    const out = metered ? uri.replace(/([?&]path=)([^&#]*)/, (m, a, p) => a + p + encodeURIComponent('?u=' + u.id)) : uri;
    const frag = encodeURIComponent(' • ' + u.name);
    return out.indexOf('#') < 0 ? out + '#' + encodeURIComponent(u.name) : out + frag;
  },
  view(u, links) {
    const set = this.live.get(u.id);
    const used = Math.round(u.used), up = Math.min(used, Math.round(u.up || 0));
    return { id: u.id, name: u.name, proto: u.proto || '', limitBytes: u.limitBytes, used, up, down: Math.max(0, used - up), lastOnline: u.lastOnline || 0, createdAt: u.createdAt, expireAt: u.expireAt, enabled: u.enabled, status: this.state(u), online: set ? set.size : 0, links };
  },
  attach(uid, a, b) {
    const u = this.get(uid); if (!u) return;
    let set = this.live.get(uid); if (!set) { set = new Set(); this.live.set(uid, set); }
    const rec = { lr: 0, lw: 0 };
    u.lastOnline = Date.now(); this.dirty = true;
    rec.tick = (final) => {
      const r = a.bytesRead || 0, w = a.bytesWritten || 0;
      const dr = Math.max(0, r - rec.lr), dw = Math.max(0, w - rec.lw); rec.lr = r; rec.lw = w;
      if (dr > 0 || dw > 0) { u.up = (u.up || 0) + dr; u.used += dr + dw; u.lastOnline = Date.now(); this.dirty = true; }
      if (!final && !this.allowed(uid)) { try { a.destroy(); b.destroy(); } catch {} }
    };
    set.add(rec); this.recs.add(rec);
    if (!this.ticker) { this.ticker = setInterval(() => { for (const r of this.recs) r.tick(false); }, 2000); if (this.ticker.unref) this.ticker.unref(); }
    a.once('close', () => { rec.tick(true); this.recs.delete(rec); set.delete(rec); if (!set.size) this.live.delete(uid); });
  }
};

const ConfigStore = {
  file: null,
  data: { configs: [] },
  catalog: {
    'VLESS-WS': { label: 'VLESS · WebSocket', desc: 'پایدار و سازگار با بیشتر کلاینت‌ها', tag: 'VL' },
    'VLESS-HTTPUpgrade': { label: 'VLESS · HTTPUpgrade', desc: 'سبک و سریع، مناسب شبکه‌های سخت‌گیر', tag: 'VU' },
    'VLESS-gRPC': { label: 'VLESS · gRPC', desc: 'اتصال چندکاناله و پایدار', tag: 'VG' },
    'VLESS-XHTTP': { label: 'VLESS · XHTTP', desc: 'پروتکل جدید مبتنی بر HTTP', tag: 'VX' },
    'VLESS-Argo': { label: 'VLESS · Argo', desc: 'عبور از تونل Cloudflare', tag: 'VA' },
    'VMess-WS': { label: 'VMess · WebSocket', desc: 'کلاسیک و سازگار با اغلب کلاینت‌ها', tag: 'VM' },
    'Trojan-WS': { label: 'Trojan · WebSocket', desc: 'شبیه ترافیک عادی وب', tag: 'TR' },
    'Hysteria2': { label: 'Hysteria2', desc: 'مبتنی بر UDP با سرعت بالا', tag: 'HY' },
    'ShadowTLS-VLESS': { label: 'ShadowTLS + VLESS', desc: 'پنهان‌سازی پشت TLS واقعی', tag: 'ST' },
    'Shadowsocks': { label: 'Shadowsocks', desc: 'کلاسیک، سبک و سازگار', tag: 'SS' },
    'WireGuard': { label: 'WireGuard', desc: 'تونل UDP سریع با فایل کانفیگ', tag: 'WG' },
    'TUIC': { label: 'TUIC', desc: 'مبتنی بر QUIC با تأخیر کم', tag: 'TU' }
  },
  init(dir) {
    if (this.file) return;
    this.file = path.join(dir, 'configs.json');
    try {
      const j = JSON.parse(fs.readFileSync(this.file, 'utf8'));
      if (j && Array.isArray(j.configs)) this.data = { configs: j.configs.filter(c => c && c.id && c.type) };
    } catch {}
  },
  save() {
    if (!this.file) return;
    try {
      fs.writeFileSync(this.file + '.tmp', JSON.stringify(this.data));
      fs.renameSync(this.file + '.tmp', this.file);
    } catch (e) {
      throw new UserError('ذخیره کانفیگ ممکن نشد: ' + e.message);
    }
  },
  protocols(nodes) {
    const seen = new Set();
    const out = [];
    for (const n of nodes) {
      if (seen.has(n.type)) continue;
      seen.add(n.type);
      const m = this.catalog[n.type] || { label: n.type, desc: '', tag: String(n.type).slice(0, 2).toUpperCase() };
      out.push({ id: n.type, label: m.label, desc: m.desc, tag: m.tag });
    }
    return out;
  },
  create(b, nodes) {
    const type = String(b.protocol || '').trim();
    if (!type) throw new UserError('یک پروتکل انتخاب کن.');
    if (!nodes.some(n => n.type === type)) throw new UserError('این پروتکل روی این سرور فعال نیست.');
    if (this.data.configs.length >= 100) throw new UserError('حداکثر ۱۰۰ کانفیگ مجاز است.');
    let name = String(b.name || '').replace(/[\r\n#]/g, ' ').trim().slice(0, 40);
    if (!name) {
      const base = (this.catalog[type] || { label: type }).label.replace(/\s*·\s*/g, '-').replace(/\s+/g, '');
      let i = this.data.configs.filter(c => c.type === type).length + 1;
      name = base + '-' + i;
      while (this.data.configs.some(c => c.name.toLowerCase() === name.toLowerCase())) { i += 1; name = base + '-' + i; }
    }
    if (this.data.configs.some(c => c.name.toLowerCase() === name.toLowerCase())) throw new UserError('این نام قبلاً استفاده شده.');
    const c = { id: crypto.randomBytes(8).toString('base64url'), name, type, createdAt: Date.now() };
    this.data.configs.push(c);
    this.save();
    return c;
  },
  remove(id) {
    const i = this.data.configs.findIndex(c => c.id === id);
    if (i < 0) throw new UserError('کانفیگ پیدا نشد.');
    const [c] = this.data.configs.splice(i, 1);
    this.save();
    return c;
  },
  view(c, nodes) {
    const node = nodes.find(n => n.type === c.type);
    const base = { id: c.id, name: c.name, type: c.type, createdAt: c.createdAt, available: !!node, uri: '', singboxJson: null, wgConf: null };
    if (!node) return base;
    base.uri = node.uri ? String(node.uri).replace(/#.*$/, '') + '#' + urlSafeEncode(c.name) : '';
    base.wgConf = node.wgConf || null;
    if (Array.isArray(node.singboxOutbound)) {
      const sb = node.singboxOutbound.length === 1 ? [Object.assign({}, node.singboxOutbound[0], { tag: c.name })] : node.singboxOutbound;
      base.singboxJson = JSON.stringify(sb, null, 2);
    } else {
      base.singboxJson = node.singboxJson || null;
    }
    return base;
  }
};

class TcpRouter {
  constructor(config, targetPorts, expressServer) {
    this.config = config;
    this.ports = targetPorts;
    this.httpServer = expressServer;
    this.server = null;
  }

  pipeToBackend(clientSocket, firstChunk, targetPort, label) {
    const backend = net.connect(targetPort, '127.0.0.1', () => {
      Stats.track(label, clientSocket, backend, firstChunk.length);
      backend.write(firstChunk);
      clientSocket.pipe(backend);
      backend.pipe(clientSocket);
      clientSocket.resume();
    });

    backend.on('error', (err) => {
      const now = Date.now();
      if (!this._lastWarns) this._lastWarns = {};
      if (!this._lastWarns[label] || now - this._lastWarns[label] > 15000) {
        Logger.warn(`ROUTER: ${label} backend :${targetPort} unreachable (${err.message})`);
        this._lastWarns[label] = now;
      }
      try { clientSocket.destroy(); } catch {}
    });

    clientSocket.on('error', () => {
      try { backend.destroy(); } catch {}
    });
  }

  attachUpgradeHandlers() {
    this.httpServer.on('upgrade', (req, socket, head) => {
      const url = req.url || '';
      const wsPath = `/${this.config.panelPath}-ws`;
      const huPath = `/${this.config.panelPath}-hu`;
      const xhPath = `/${this.config.panelPath}-xh`;
      const trPath = `/${this.config.panelPath}-trojan`;
      const vmPath = `/${this.config.panelPath}-vmess`;

      let destPort = null;
      let label = 'Unknown Upgrade';

      if (url.startsWith(wsPath) && this.ports.vlessWs) {
        destPort = this.ports.vlessWs;
        label = 'VLESS-WS';
      } else if (url.startsWith(huPath) && this.ports.vlessHu) {
        destPort = this.ports.vlessHu;
        label = 'VLESS-HTTPUpgrade';
      } else if (url.startsWith(xhPath) && this.ports.xray) {
        destPort = this.ports.xray;
        label = 'VLESS-XHTTP';
      } else if (url.startsWith(vmPath) && this.ports.vmessWs) {
        destPort = this.ports.vmessWs;
        label = 'VMess-WS';
      } else if (url.startsWith(trPath) && this.ports.trojanWs) {
        destPort = this.ports.trojanWs;
        label = 'Trojan-WS';
      }

      if (!destPort) {
        socket.write('HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n');
        socket.destroy();
        return;
      }

      const um = /[?&]u=([A-Za-z0-9_-]{6,40})(?=&|$)/.exec(url);
      const uid = um ? um[1] : null;
      const fwdUrl = uid ? url.replace(/([?&])u=[A-Za-z0-9_-]+(&|$)/, (m, a, b) => (b ? a : '')).replace(/[?&]$/, '') : url;
      if (uid ? !UserStore.allowed(uid) : UserStore.data.settings.requireUser) {
        socket.write('HTTP/1.1 403 Forbidden\r\nConnection: close\r\n\r\n');
        socket.destroy();
        return;
      }

      const backend = net.connect(destPort, '127.0.0.1', () => {
        let headersStr = `${req.method} ${fwdUrl} HTTP/${req.httpVersion}\r\n`;
        for (let i = 0; i < req.rawHeaders.length; i += 2) {
          headersStr += `${req.rawHeaders[i]}: ${req.rawHeaders[i + 1]}\r\n`;
        }
        headersStr += '\r\n';

        backend.write(headersStr);
        if (head && head.length > 0) {
          backend.write(head);
        }

        try { socket.setNoDelay(true); backend.setNoDelay(true); } catch {}
        Stats.track(label, socket, backend, 0);
        if (uid) UserStore.attach(uid, socket, backend);
        socket.pipe(backend);
        backend.pipe(socket);
      });

      backend.on('error', () => {
        try { socket.destroy(); } catch {}
      });

      socket.on('error', () => {
        try { backend.destroy(); } catch {}
      });
    });
  }

  start() {
    this.attachUpgradeHandlers();

    this.server = net.createServer((socket) => {
      socket.once('data', (chunk) => {
        socket.pause();

        if (this.config.enable.socks && this.ports.socks && chunk.length >= 2 && chunk[0] === 0x05) {
          this.pipeToBackend(socket, chunk, this.ports.socks, 'SOCKS5');
          return;
        }

        if (chunk.length >= 3 && chunk[0] === 0x16 && chunk[1] === 0x03) {
          const sni = parseClientHelloSni(chunk);
          let target = null;

          if (this.config.enable.shadowTlsVless && this.ports.shadowTls && sni === this.config.shadowTls.sni) {
            target = { port: this.ports.shadowTls, label: 'ShadowTLS-VLESS' };
          } else if (this.config.enable.shadowTlsVless && this.ports.shadowTls) {
            target = { port: this.ports.shadowTls, label: 'ShadowTLS-Fallback' };
          }

          if (target) {
            this.pipeToBackend(socket, chunk, target.port, target.label);
            return;
          }
        }

        if (this.config.enable.httpProxy && this.ports.httpProxy) {
          const headerSnippet = chunk.toString('latin1', 0, Math.min(chunk.length, 256));
          if (/^CONNECT /i.test(headerSnippet) || /^(GET|POST|HEAD) https?:\/\//i.test(headerSnippet)) {
            this.pipeToBackend(socket, chunk, this.ports.httpProxy, 'HTTP-Proxy');
            return;
          }
        }

        if (this.config.enable.vlessGrpc && this.ports.vlessGrpc && chunk.length >= 16) {
          if (chunk.toString('latin1', 0, 16) === 'PRI * HTTP/2.0\r\n') {
            this.pipeToBackend(socket, chunk, this.ports.vlessGrpc, 'VLESS-gRPC');
            return;
          }
        }

        const firstWords = chunk.toString('latin1', 0, Math.min(chunk.length, 8));
        const isHttpVerb = /^(GET|POST|PUT|HEAD|OPTIONS|DELETE|PATCH|TRACE) /i.test(firstWords);

        if (!isHttpVerb && this.config.enable.shadowsocks && this.ports.shadowsocks) {
          this.pipeToBackend(socket, chunk, this.ports.shadowsocks, 'Shadowsocks');
          return;
        }

        socket.unshift(chunk);
        this.httpServer.emit('connection', socket);
        socket.resume();
      });

      socket.on('error', () => {});
    });

    return new Promise((resolve, reject) => {
      this.server.listen(this.config.publicPort, '0.0.0.0', () => {
        Logger.success(`Public TCP multiplexer listening on 0.0.0.0:${this.config.publicPort}`);
        resolve(this.server);
      });
      this.server.on('error', reject);
    });
  }

  stop() {
    if (this.server) {
      try { this.server.close(); } catch {}
    }
  }
}

async function resolvePublicHost(config) {
  if (config.forceHost) return config.forceHost;
  if (config.domain) return config.domain;
  if (process.env.CFIP) return process.env.CFIP;
  if (process.env.DOMAIN || process.env.SB_DOMAIN) return process.env.DOMAIN || process.env.SB_DOMAIN;

  try {
    const res = await axios.get('https://api.ipify.org?format=text', { timeout: 3500 });
    if (res.data && typeof res.data === 'string' && res.data.trim()) {
      return res.data.trim();
    }
  } catch {}

  try {
    const res = await axios.get('https://ifconfig.me/ip', { timeout: 3500 });
    if (res.data && typeof res.data === 'string' && res.data.trim()) {
      return res.data.trim();
    }
  } catch {}

  try {
    const res = await axios.get('https://1.1.1.1/cdn-cgi/trace', { timeout: 3500 });
    if (res.data && typeof res.data === 'string') {
      const match = res.data.match(/ip=([^\r\n]+)/);
      if (match && match[1]) return match[1].trim();
    }
  } catch {}

  return '127.0.0.1';
}

async function startGate(userConfig = {}) {
  Logger.quiet = true;
  try { console.clear(); } catch {}

  const config = buildConfig(userConfig);

  const stateMgr = new StateManager(config.paths, config);
  const state = stateMgr.loadOrCreate();
  Logger.item('UUID', state.uuid);

  const resolvedHost = await HostDetect.detectStartup(config, resolvePublicHost);
  stateMgr.setPublicIp(resolvedHost);
  Logger.item('Resolved Host', resolvedHost);

  const allocatedPorts = {};
  if (config.enable.vlessWs) allocatedPorts.vlessWs = await allocatePorts();
  if (config.enable.vmessWs) allocatedPorts.vmessWs = await allocatePorts();
  if (config.enable.vlessHttpUpgrade) allocatedPorts.vlessHu = await allocatePorts();
  if (config.enable.vlessGrpc) allocatedPorts.vlessGrpc = await allocatePorts();
  if (config.enable.trojanWs) allocatedPorts.trojanWs = await allocatePorts();
  if (config.enable.shadowTlsVless) allocatedPorts.shadowTls = await allocatePorts();
  if (config.enable.shadowsocks) allocatedPorts.shadowsocks = await allocatePorts();
  if (config.enable.socks) allocatedPorts.socks = await allocatePorts();
  if (config.enable.httpProxy) allocatedPorts.httpProxy = await allocatePorts();
  if (config.enable.vlessXhttp) allocatedPorts.xray = await allocatePorts();

  Logger.section('Engines & Binaries');
  const binManager = new BinaryManager(config);

  const hasSingBox = await binManager.ensureSingBox();
  let hasXray = false;
  if (config.enable.vlessXhttp) {
    hasXray = await binManager.ensureXray();
  }
  let hasCloudflared = false;
  if (config.enable.argo) {
    hasCloudflared = await binManager.ensureCloudflared();
  }

  let singboxInstance = null;
  if (hasSingBox) {
    singboxInstance = new SingBoxEngine(config, stateMgr, allocatedPorts);
    singboxInstance.start();
    startWatchdog(singboxInstance, 'sing-box');
  } else {
    Logger.warn('sing-box binary could not be started. (Mock/offline mode active).');
  }

  let xrayInstance = null;
  if (hasXray && allocatedPorts.xray) {
    xrayInstance = new XrayEngine(config, stateMgr, allocatedPorts.xray);
    xrayInstance.start();
  }

  let argoInstance = null;
  let argoDomain = null;
  if (hasCloudflared && config.enable.argo) {
    argoInstance = new ArgoTunnel(config, config.publicPort);
    argoDomain = await argoInstance.start();
  }

  const linkGen = new LinkGenerator(config, stateMgr.state, resolvedHost);
  const compatNodes = linkGen.getAllNodes({ compat: 'v2ray', argoDomain, allowLocalHostLinks: config.allowLocalHostLinks });
  const allNodes = linkGen.getAllNodes({ compat: 'full', argoDomain, allowLocalHostLinks: true });
  const links = compatNodes.map(n => n.uri);
  const clashYaml = linkGen.buildClashMetaYaml(allNodes);
  const singboxJson = linkGen.buildSingBoxClientJson(allNodes);

  stateMgr.setLinks(links, clashYaml, singboxJson);
  HostDetect.rebuild = () => {
    const lg = new LinkGenerator(config, stateMgr.state, resolvedHost);
    const cn = lg.getAllNodes({ compat: 'v2ray', argoDomain, allowLocalHostLinks: config.allowLocalHostLinks });
    const an = lg.getAllNodes({ compat: 'full', argoDomain, allowLocalHostLinks: true });
    stateMgr.setLinks(cn.map((n) => n.uri), lg.buildClashMetaYaml(an), lg.buildSingBoxClientJson(an));
  };

  const engineStatusGetter = () => ({
    singbox: !!(singboxInstance && singboxInstance.process && !singboxInstance.process.killed),
    xray: !!(xrayInstance && xrayInstance.process && !xrayInstance.process.killed),
    argo: !!(argoInstance && argoInstance.process && !argoInstance.process.killed)
  });

  const { server: expressServer } = createHttpPanel(config, stateMgr, engineStatusGetter, () => resolvedHost);
  const tcpRouter = new TcpRouter(config, allocatedPorts, expressServer);
  await tcpRouter.start();

  const panelUrl = HostDetect.panelUrl(config, resolvedHost);
  Logger.quiet = true;
  const adminKey = (Extras.admin && Extras.admin.key) || config.panelToken || '';
  const adminLink = panelUrl + (adminKey ? '#key=' + encodeURIComponent(adminKey) : '');
  console.log(`${ANSI.bold}${ANSI.electric}P A R H A M${ANSI.reset}`);
  console.log(`\x1b]8;;${adminLink}\x07Open Link\x1b]8;;\x07`);
  console.log(`Admin Link: ${adminLink}`);

  const shutdown = () => {
    if (!Logger.quiet) Logger.info('Stopping Parham Confing...');
    if (singboxInstance) singboxInstance.stop();
    if (xrayInstance) xrayInstance.stop();
    if (argoInstance) argoInstance.stop();
    if (tcpRouter) tcpRouter.stop();
    process.exit(0);
  };

  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);

  return {
    config,
    state: stateMgr.state,
    nodes: compatNodes,
    allNodes,
    panelUrl,
    allocatedPorts,
    tcpRouter,
    singboxInstance,
    xrayInstance,
    argoInstance,
    shutdown
  };
}

if (require.main === module) {
  startGate(BK_CONFIG).catch(err => {
    console.error('[FATAL] Failed to start Parham Confing:', err);
    process.exit(1);
  });
}

module.exports = {
  BK_CONFIG,
  startGate
};
